#include "../build_config.h"
// Crusaders Mainframe — reconciling the bridge's idea of which courts are lit
// against what the Mega says with `!STATE`.
//
// WHY THE BRIDGE CANNOT JUST TRUST THE EVENTS
// -------------------------------------------
// The Mega reports a release with `!EVT,AUTOOFF,<court>` or `!EVT,OFF,<court>`,
// and the bridge's Release event — the number a dispute about a 45-minute
// booking turns on — is produced from that. But the Mega's TX ring is 64 bytes
// draining at ~1 byte/ms, and four courts expiring together put four events and
// a `!STATE` on it in one pass; something drops. Nothing retries a dropped EVT,
// and the bridge used to read `!STATE` "for diagnostics only", so one dropped
// release left the court held forever in the bridge's books and the club's
// record showed the full booked length (review A2-6).
//
// `!STATE` goes out on every change AND every ten seconds. Whichever messenger
// survives, the mask carries the truth: a bit cleared while the bridge believes
// the court is held IS the release, and a bit set while the bridge believes it
// is dark is a court somebody lit while the bridge was rebooting.
//
// WHY EXACTLY ONE RELEASE PER LIGHTING
// ------------------------------------
// The EVT and the STATE describe the same release. If the EVT arrived first the
// bridge already cleared its held flag, so the STATE finds nothing to reconcile;
// if the STATE arrived first the held flag is already clear when the EVT turns
// up, and the event handler must drop it. Both orders produce one Release.
//
// WHY THE GRACE PERIOD
// --------------------
// A `!STATE` is thirty-odd bytes — thirty milliseconds on the wire — and the
// periodic one may already be in flight when the bridge sends `!ON`. It then
// arrives showing the court dark a few milliseconds after the bridge marked it
// held, and reconciling THAT would synthesise a release for a court that is
// coming on. So a disagreement is acted on only once the bridge's own belief is
// older than the window in which a stale frame could still be arriving. The
// next periodic frame, ten seconds on, settles a real disagreement.
//
// No Arduino headers, no heap. Compiles for Xtensa and the host.

#ifndef CRUSADERS_BRIDGELOGIC_STATERECONCILE_H
#define CRUSADERS_BRIDGELOGIC_STATERECONCILE_H

#include <stdint.h>

#include "../timebase/TimeBase.h"

namespace bridgelogic {

/// Courts a box drives; also the width of the `!STATE` mask.
inline constexpr uint8_t kStateCourts = 4U;

/// How old the bridge's belief about a court must be before a `!STATE` that
/// contradicts it is acted on. Longer than any frame that could have been in
/// flight when the belief was formed; far shorter than the periodic interval,
/// so a genuine disagreement is still settled by the next periodic frame.
inline constexpr uint32_t kReconcileGraceMs = 2000UL;

/// The bridge's belief about one court.
///
/// `held` is a separate flag rather than "sinceMs == 0 means not held", which is
/// the rule TimeBase.h states outright: every uint32_t is a legal millis()
/// reading. `sinceMs` is when the belief was last CHANGED — when the court was
/// lit while held, when it was released while not — which is what the grace
/// period above is measured from.
struct HeldState {
  uint32_t sinceMs = 0U;
  bool held = false;
};

/// What to do about one court after reading a `!STATE`.
enum class CourtAction : uint8_t {
  /// The Mega and the bridge agree, or disagree too recently to act on.
  None = 0U,
  /// The Mega says dark, the bridge says held: the release event was lost.
  /// Queue the Release with `heldMs` and forget the court.
  SynthesizeRelease = 1U,
  /// The Mega says lit, the bridge says dark: adopt it as held from now, so a
  /// later release reports at least the time this bridge saw it on.
  AdoptHeld = 2U,
};

struct Reconciliation {
  CourtAction action[kStateCourts] = {};
  /// For SynthesizeRelease: how long the court was held, by the bridge's clock.
  uint32_t heldMs[kStateCourts] = {};
};

/// Parses the `!STATE` mask argument: decimal, no sign, no whitespace, at most
/// 15. False on anything else — a mask this build cannot read must not be
/// reconciled against.
bool parseStateMask(const char* arg, uint8_t& mask);

/// Parses one of `!STATE`'s four per-court remaining-seconds arguments:
/// decimal, no sign, no whitespace, at most 65535. False on anything else —
/// including an absent argument, which an older Mega that sends the mask alone
/// produces — and `seconds` is left untouched.
///
/// The Mega publishes what its own relay timer has left, on every change and
/// every ten seconds. Reading it is what corrects a relay deadline this half
/// only BELIEVES it moved (bridgelogic::Relight::observeRelayRemaining).
bool parseStateSeconds(const char* arg, uint16_t& seconds);

/// Compares `mask` against `held` and says what to do about each court.
Reconciliation reconcile(uint8_t mask, const HeldState held[kStateCourts], uint32_t nowMs);

/// The belief about a court after an `!ON` was ATTEMPTED: held from `nowMs`
/// only when the frame actually left the bridge, `previous` otherwise.
///
/// The bridge used to mark the court held whether or not the `!ON` was sent. A
/// full TX ring or a dead cable then left a court "held" in this half's books
/// that the Mega never lit, and the next `!STATE` — correctly showing it dark —
/// synthesised a Release for a session that never happened. A frame that did
/// not go leaves the books alone; the member is told to try again.
HeldState afterOnAttempt(const HeldState& previous, bool sent, uint32_t nowMs);

/// What the member reads when the `!ON` could not be sent. The screen already
/// said "COURT C 45 MIN" — painted first, on purpose — so this replaces a
/// promise the lights did not keep.
inline constexpr char kOnNotSentLine1[] = "TRY AGAIN";
inline constexpr char kOnNotSentLine2[] = "SCAN TO START";

} // namespace bridgelogic

#endif // CRUSADERS_BRIDGELOGIC_STATERECONCILE_H
